def rearange_string(s):
    from collections import Counter

    char_count = Counter(s)

    result = []
    while char_count:
        for char, count in char_count.items():
            if count > 0:
                result.append(char)
                char_count[char] -= 1
                if char_count[char] == 0:
                    del char_count[char]
                break

    return ''.join(result)
