def comb_sort(arr):
    gap = len(arr)
    sorted = False

    while not sorted:
        gap = max(1, int(gap / 1.3))
        sorted = False

        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False
            else:
                sorted = True

    return arr
```

