def magic_square_test(square):
    n = len(square)
    total = n * (n ** 2 + 1) / 2

    for i in range(n):
        row_sum = sum(square[i])
        col_sum = 0
        for j in range(n):
            col_sum += square[j][i]
        if row_sum != total or col_sum != total:
            return False

    diagonal_sum1 = 0
    for i in range(n):
        diagonal_sum1 += square[i][i]
    diagonal_sum2 = 0
    for i in range(n):
        diagonal_sum2 += square[i][n - 1 - i]
    if diagonal_sum1 != total or diagonal_sum2 != total:
        return False

    return True
```

