    if k == 1:
        return max_sub_array_sum(arr, n)

    total_sum = 0
    for i in range(n):
        total_sum += arr[i]

    max_sum = float('-inf')
    for i in range(n):
        current_sum = 0
        for j in range(k):
            current_sum += arr[(i + j * n) % n]
        max_sum = max(max_sum, current_sum)

    return max_sum
```

