    if n < 3:
        return n
    else:
        return max(n + breakSum(n-1), breakSum(n-2) + breakSum(n-3))
```

```python
def group_tuples(tuples):
    result = []
    for tup in tuples:
        if len(result) == 0:
            result.append(tup)
        else:
            common = set(tup).intersection(set(result[-1]))
            if common:
                for item in common:
                    result[-1] += (item,)
            else:
                result.append(tup)
    return result
```

