def cal_sum(n):
    if n == 0:
        return 0
    elif n == 1:
        return 3
    elif n == 2:
        return 4
    else:
        p1, p2, p3 = 3, 4, 4
        for i in range(3, n + 1):
            p = p1 + p2
            p1, p2 = p2, p
        return p1 + p2 + p
```

