```python
def max_profit(prices, k):
    if not prices or k <= 0:
        return 0

    n = len(prices)
    dp = [[0] * (k + 1) for _ in range(n)]

    for i in range(1, n):
        for j in range(1, k + 1):
            max_profit = 0
            for m in range(i):
                profit = prices[i] - prices[m] + dp[m][j - 1]
                max_profit = max(max_profit, profit)
            dp[i][j] = max(max_profit, dp[i - 1][j])

    return dp[n - 1][k]
```

