```python
def is_subset_sum(arr, target, n): 
    if target == 0: 
        return True
    if n == 0 and target != 0: 
        return False
    if arr[n-1] > target: 
        return is_subset_sum(arr, target, n-1) 
    return is_subset_sum(arr, target, n-1) or is_subset_sum(arr, target-arr[n-1], n-1) 
```

