def extract_symmetric(tuples_list):
    symmetric_pairs = set()
    for pair in tuples_list:
        if pair[0] == pair[1]:
            symmetric_pairs.add(pair)
        elif pair[0] > pair[1]:
            symmetric_pairs.add((pair[1], pair[0]))
    return symmetric_pairs
```

